import json,re
from pathlib import Path
summaries={
'hece':'Türkçede her hecede bir ünlü bulunur. Bir kelimenin hece sayısını ünlüleri sayarak bulabiliriz. İki ünlü arasındaki tek ünsüz sonraki heceye geçer. Yan yana gelen iki ünsüz genellikle ayrı hecelerde yer alır. Satır sonunda kelimeyi hece sınırından böler, tek harfi yalnız bırakmayız.',
'nokta':'Nokta, tamamlanmış haber cümlelerinin sonuna konur. Duygu veya soru bildiren cümleler başka işaretlerle tamamlanabilir. Nokta bazı kısaltmaların sonunda da kullanılır. Sayılardan sonra geldiğinde sıra anlamı verebilir. Noktanın görevini anlamak için cümlenin ne anlattığını incelemeliyiz.',
'kisa-cizgi':'Kısa çizgi, sözcükleri hecelerine ayırırken kullanılır. Satıra sığmayan bir sözcüğü hece sınırından bölmemize de yardım eder. Birleşen iki satırda sözcüğün anlamı değişmez. Kısa çizgiyi konuşma çizgisiyle karıştırmamalıyız. Kelimeyi bölerken satırın başında veya sonunda tek harf bırakmayız.',
'isim-fiil':'İsimler varlıkları, kavramları ve duyguları karşılar. Fiiller yapılan bir işi, oluşu veya hareketi anlatır. Bir sözcüğün görevini anlamak için kullanıldığı cümleye bakarız. Fiiller uygun bir kişi ve zamanla çekimlenebilir. Aynı sözcük farklı cümlelerde farklı görevler üstlenebilir.',
'buyuk-harf':'Cümlelerin ilk sözcüğü büyük harfle başlar. Kişi ve yer adları gibi özel adların ilk harfi de büyüktür. Dil ve millet adlarını büyük harfle yazarız. Bir sözcüğün özel ad olup olmadığını cümledeki kullanımından anlarız. Yazdıktan sonra büyük harflerin yerini yeniden kontrol ederiz.',
'virgul':'Virgül, eş görevli sözcükleri birbirinden ayırır. Sıralanan kısa cümleler arasında da kullanılabilir. Seslenme sözlerinden sonra virgül koyabiliriz. Virgül, okurken anlamı doğru bölümlere ayırmamıza yardımcı olur. Bağlaçların her iki yanına gelişigüzel virgül koymamalıyız.',
'soru-isareti':'Soru işareti, soru anlamı taşıyan cümlelerin sonuna konur. Bir cümle soru sözcüğüyle veya soru ekiyle kurulabilir. Soru eki kendinden önceki sözcükten ayrı yazılır. Cümlenin gerçekten soru sorup sormadığını düşünmeliyiz. Cümlenin son işaretini anlamına göre seçmeliyiz.',
'ismi-niteleyen':'İsimlerden önce gelen bazı sözcükler onların özelliklerini anlatır. Bu sözcükler renk, biçim, durum veya sayı bildirebilir. Bir isme nasıl sorusunu sorarak niteliğini bulabiliriz. Hangi ve kaç soruları da ismi belirten sözcükleri fark etmemize yardım eder. Özellik bildiren sözcük ile onun belirttiği ismi birlikte incelemeliyiz.',
'sifat-fiil':'Bazı fiil kökenli sözcükler cümlede bir ismin özelliğini anlatır. Bu yapılar bir hareketle o hareketin ilgili olduğu varlık arasında bağ kurar. Okuyan çocuk ifadesinde okuyan sözcüğü çocuğu niteler. Bu tür yapılara bakarken hem sözcüğün kökünü hem de cümledeki görevini düşünürüz. Asıl amaç, bu yapıların cümleye kattığı anlamı fark etmektir.',
'ekleme':'Ekleme bildiren ifadeler önceki bilgiye yeni bir bilgi katar. Ayrıca, üstelik ve hatta bu amaçla kullanılabilir. Yeni bilginin önceki cümleyle ilişkili olması gerekir. Bu bağlantılar düşünceler arasında akıcı bir geçiş sağlar. Hangi bağlantıyı seçeceğimize cümlenin anlamına göre karar veririz.',
'unlem':'Ünlem işareti, güçlü duyguların anlatıldığı cümlelerin sonunda kullanılır. Sevinç, korku, şaşırma ve üzüntü bu duygular arasında yer alır. Uyarı ve seslenmelerde de ünlem kullanılabilir. Cümleyi okurken ses tonumuz, anlatılan duyguyu yansıtır. Her cümlenin sonuna ünlem koymak yerine anlamı değerlendirmeliyiz.',
'uzun-cizgi':'Konuşma çizgisi, metindeki karşılıklı konuşmaları göstermeye yarar. Konuşan kişinin sözünden önce satır başında kullanılır. Her yeni konuşmacının sözü ayrı bir satırda başlayabilir. Konuşma çizgisi kısa çizgiden daha uzundur. Bu işaret metni okurken kimin konuştuğunu izlememizi kolaylaştırır.',
'isimler':'İsimler varlıkların, kavramların ve duyguların adlarıdır. Tek bir varlığı karşılayan özel adlar büyük harfle başlar. Aynı türden varlıkları karşılayan sözcüklere tür adı denir. İsimler tek bir varlığı veya birden fazla varlığı anlatabilir. Bir ismin özelliğini belirlerken cümledeki anlamını incelemeliyiz.',
'amac':'Amaç bildiren ifadeler bir işin hangi hedefle yapıldığını açıklar. Bir cümleye hangi amaçla sorusunu sorarak amacı bulabiliriz. İçin ve üzere gibi sözcükler amaç ilişkisi kurabilir. Amaç, henüz ulaşılmak istenen sonucu gösterir. Neden ile amacı ayırırken gerçekleşmiş sebebe mi yoksa hedefe mi bakıldığını düşünmeliyiz.',
'duygu':'Cümleler yalnızca bilgi değil, duygu da taşır. Dilek, pişmanlık, şaşırma ve sevinç farklı duygu durumlarıdır. Keşke sözcüğü bağlama göre dilek veya pişmanlık bildirebilir. Bir cümlenin duygusunu anlamak için bütününü okumalıyız. Noktalama ve ses tonu da duyguyu anlamamıza yardımcı olur.',
'sayilar':'Sayılar metnin amacına göre yazıyla veya rakamla gösterilebilir. Birden fazla sözcükten oluşan sayılar ayrı yazılır. Sıra bildiren sayılar ekle veya noktayla gösterilebilir. Tarih ve saatlerde sayıların kullanımına dikkat ederiz. Sayıları yazdıktan sonra eklerini ve işaretlerini kontrol ederiz.',
'uc-nokta':'Üç nokta, tamamlanmamış ifadelerin sonunda kullanılabilir. Anlatımda söylenmeyen bir bölüm olduğunu düşündürür. Verilen örneklerin devam edebileceğini de gösterebilir. Üç nokta birbiri ardına gelen üç noktadan oluşur. Cümlenin tamamlanıp tamamlanmadığını düşünerek bu işareti kullanırız.',
'kesme':'Kesme işareti, özel adlara gelen bazı ekleri ayırır. Kişi ve yer adlarının eklerine dikkat etmeliyiz. Kısaltmalara ve sayılara gelen bazı eklerde de kesme kullanılır. Her sözcüğün ekini kesmeyle ayırmak doğru değildir. İşaretin gerekip gerekmediğini sözcüğün türüne göre belirleriz.',
'karsilastirma':'Karşılaştırma yaparken iki varlık veya durum arasındaki ilişkiyi belirtiriz. Daha ve en gibi sözcükler özelliklerin derecesini gösterebilir. Gibi sözcüğü benzerlik kurmamıza yardımcı olur. Farklılık bildiren ifadeler ortak olmayan özellikleri vurgular. Karşılaştırmada hangi özelliğin ele alındığını bulmalıyız.',
'ozet':'Özet bildiren ifadeler anlatılanların temel düşüncesini toparlar. Kısacası ve özetle bu amaçla kullanılabilir. Özet cümlesi önceki anlatımla anlamca uyumlu olmalıdır. Özetlerken gereksiz ayrıntıları çıkarırız. Ana düşünceyi kendi sözlerimizle kısa ve açık biçimde anlatırız.',
'zamir':'Bazı sözcükler cümlede bir ismin yerini tutar. Ben, sen ve o kişi adlarının yerine kullanılabilir. Bu, şu ve onlar gibi sözcüklerin hangi varlığı gösterdiğini bağlamdan anlarız. İsmin yerini tutan sözcükler gereksiz tekrarları azaltır. Bu sözcükleri yorumlarken önceki ve sonraki cümleleri de okumalıyız.',
'zaman-baglac':'Zaman bildiren bağlantılar olayların sırasını anlamamıza yardım eder. Önce ve sonra sözcükleri farklı zaman adımlarını gösterir. Bu sırada ifadesi aynı zamanda gerçekleşen bir olaya işaret edebilir. Olayları sıralarken bağlantı sözcükleriyle birlikte bütün anlamı da inceleriz. Böylece anlatımdaki zaman ilişkisini doğru kurarız.',
'tirnak':'Tırnak işareti, başkasından aktarılan sözleri göstermekte kullanılabilir. Özellikle vurgulanan bir sözün sınırlarını da belirtebilir. Açılan tırnağın kapanmasına dikkat etmeliyiz. Alıntı sözün kendi noktalaması anlamına uygun olmalıdır. Tırnak içindeki sözü çevresindeki cümleyle birlikte okuruz.',
'anlam-butunlugu':'Bir cümledeki sözcükler anlam bakımından birbiriyle uyumlu olmalıdır. Aynı durumu çelişkili biçimde anlatan sözcükler anlamı bozabilir. Kesinlik ile olasılık bildiren sözcükleri dikkatle seçmeliyiz. Cümlede fazladan veya yanlış kullanılan bir sözcük olup olmadığını kontrol ederiz. Düzeltme yaparken cümlenin temel düşüncesini koruruz.',
'yeniden-kurma':'Bir cümleyi kendi sözlerimizle yeniden anlatabiliriz. Yeniden kurarken cümlenin temel anlamını korumalıyız. Sözcüklerin yerini değiştirmek tek başına yeterli olmayabilir. Uygun eş anlamlı ifadelerden ve farklı cümle yapılarından yararlanabiliriz. Son olarak yeni cümle ile ilk cümleyi anlam yönünden karşılaştırırız.',
'ornek':'Örnekler bir düşüncenin daha iyi anlaşılmasını sağlar. Örneğin ve mesela sözcükleri örneğe geçişi gösterebilir. Verilen örneğin açıklanan düşünceyle ilişkili olması gerekir. Birden fazla örnek arasında anlamca uyum kurmalıyız. Örneklerden yola çıkarak anlatılan genel düşünceyi bulabiliriz.',
'tekrar':'Yazdığımız bir metni tamamladıktan sonra yeniden okumalıyız. Cümle başlangıçlarını ve özel adların büyük harflerini kontrol ederiz. Cümle sonlarındaki işaretleri anlama göre seçeriz. Eklerin, sayıların ve kısaltmaların yazımını da gözden geçiririz. Düzeltmelerimiz metnin daha açık ve anlaşılır olmasını sağlar.',
'tahmin':'Tahmin, ipuçlarından yararlanarak bir sonuca ulaşmaya çalışmaktır. Sanırım, galiba ve belki gibi sözcükler kesin olmayan bir yargı bildirebilir. Tahminlerimizi metindeki veya görseldeki bir ipucuna dayandırmalıyız. Yeni bilgi geldiğinde tahminimizi değiştirebiliriz. Tahmin ile kesin bilgiyi birbirinden ayırmalıyız.'}
themes=[];private=[]
for f in sorted(Path('content/turkce/5-sinif').glob('tema-*.json')):
 d=json.loads(f.read_text());lessons=[]
 for k in d['konular']:
  slug=k['kod'].split('-',2)[2];summary=summaries[slug]
  extra=[q['soru']+' → '+q['dogru'] for q in k['testler'] if not any(q['dogru'] in old for old in k['ornekler'])]
  examples=(k['ornekler']+extra+[q['soru']+' → '+q['dogru'] for q in k['testler'] if q['soru']+' → '+q['dogru'] not in extra])[:5]
  lessons.append(dict(id=k['kod'],title=k['ad'],summary=summary,examples=examples[:5],questionCount=8))
  private.append(dict(id=k['kod'],questions=[dict(id=q['id'],prompt=q['soru'],choices=q['secenekler'],answer=q['dogru'],explanation=q['aciklama']) for q in k['testler']]))
 themes.append(dict(number=d['tema'],title=d['temaAdi'],lessons=lessons))
Path('content/turkce/study-5.json').write_text(json.dumps(dict(grade=5,themes=themes),ensure_ascii=False,indent=2)+'\n')
quote=lambda x:"'"+x.replace("'","''")+"'"
Path('supabase/member-release/study-catalog.sql').write_text('-- Generated by tools/build-study-catalog.py from reviewed grade-five topics.\ninsert into turkce_private.study_catalog(lesson_id,questions) values\n'+',\n'.join('('+quote(k['id'])+','+quote(json.dumps(k['questions'],ensure_ascii=False))+'::jsonb)' for k in private)+'\non conflict(lesson_id) do update set questions=excluded.questions;\n')
print(len(themes),'themes;',len(private),'lessons;',sum(len(x['questions']) for x in private),'test questions')
